function stage5(){if(U.buildFail)return{h:`<div class="shdr"><button class="hib" data-a="back">${ic('back')}</button><div class="t"><b>Build</b><span>${esc(titleOf(S))}</span></div></div>`,b:`<div class="pad col g16" style="align-items:flex-start"><div class="note crit">${ic('warn','s')}<span><b>We could not build your days.</b><br>Your picks and settings are kept.</span></div><button class="btn pri" data-a="build">Try again</button><button class="lnk" data-a="back">Back to Days and driving</button></div>`,f:''};
 return{h:`<div class="shdr"><div class="t" style="padding-left:14px"><b>Building your days</b><span>${esc(titleOf(S))}</span></div></div>`,b:`<div class="pad col g16" style="align-items:center;padding-top:64px"><div class="spin"></div><div id="progt" class="title">Working out drive times · 0 of ${Math.max(30,S.picks.length*4)}</div><div id="prog" class="bartrack" style="width:100%"><i style="width:0"></i></div><p class="small" style="text-align:center">Choosing bases, ordering stops by road, filling each day. Your picks stay as they are.</p></div>`,f:''}}
/* ---------- plan helpers ---------- */
function find(pid){const pl=S.plan;for(const d of pl.days){const i=d.items.findIndex(x=>x.pid===pid);if(i>=0)return{d,i,it:d.items[i]}}return null}
function kept(it){return it.locked||it.placed||(it.fromTrip&&!S.releaseTrip)}
function keptCounts(){let l=0,p=0,t=0;S.plan.days.forEach(d=>d.items.forEach(i=>{if(i.locked)l++;else if(i.placed)p++;else if(i.fromTrip&&!S.releaseTrip)t++}));return{l,p,t}}
