function planHdr(){const w=whenInfo(S);return `<div class="shdr"><span class="idsq" style="background:${S.identity}" aria-hidden="true"></span><div class="t" style="padding-left:0"><b>${esc(titleOf(S))}</b><span><span id="autosave">${esc(U.status||'On this phone')}</span>${S.plan?' · '+S.plan.days.length+' days':''}</span></div>${isDesk()&&S.stage===7?`<button class="btn sm hdrbtn" data-a="sheet" data-v="settings">${ic('menu','s')} Settings${pending().length?' ('+pending().length+')':''}</button><button class="btn sm hdrbtn pri" data-a="goReview">Review ${ic('chev','s')}</button>`:''}<button class="hib" data-a="menu" aria-label="Plan menu" aria-expanded="${U.menu}">${ic('dots')}</button></div>${U.menu?planMenu():''}`}
