 if(S.flyMode==='fly'){const a=AIRPORTS[first?S.arrive:S.leave],code=first?S.arrive:S.leave;const m=first?drive(a,d.base):drive(d.items.length?PL[d.items[d.items.length-1].pid]:d.base,a);
  return `<div class="gt"><div class="flex g8">${ic('plane')}<div class="grow"><div class="title">${first?'Fly into':'Fly home from'} ${esc(a.n)} (${code})</div><div class="meta">${first?fd(m)+' ≈ to '+esc(d.base.name)+' · hire car at '+code:'Return the car, then fly from '+fd(m)+' ≈ away'}</div>${first&&U.justBuilt?`<div class="meta">From ${esc(AIRPORTS[S.airFrom].n)} (${S.airFrom})</div>`:''}</div><button class="lnk sm" data-a="sheet" data-v="getting">Change</button></div></div>`}
