/* ---------- keyboard model (FLOW 7.1, components 8.1) ----------
   Focus a stop (Tab, then Up and Down between stops). Space lifts it; Up and Down move it in the day, Left or PageUp and Right or
   PageDown move it to the previous or next day; Enter drops it and keeps it there (one Undo step); Escape puts it back.
   Single-letter keys (M then a day number, S swap, A add, ? list) work only while a stop has focus, never in a field, and one
   setting turns them off (WCAG 2.1.4). Delete removes the focused stop. */
function rowBtn(pid){return document.querySelector('.it[data-pid="'+pid+'"] button[data-row]')}
function focusRow(pid){const b=rowBtn(pid);if(b)b.focus()}
function posText(pid){const f=find(pid);return f?'position '+(f.i+1)+' of '+f.d.items.length+' on Day '+(f.d.n+1):''}
function kbLift(pid){const f=find(pid);if(!f)return;U.kb={pid,snap:J(S.plan),from:f.d.n+':'+f.i};U.menu=false;render();focusRow(pid);say('Lifted '+PL[pid].name+', '+posText(pid)+'. Arrow keys move it, Enter drops it, Escape cancels.')}
function kbMoveBy(dir){const k=U.kb,f=find(k.pid);if(!f)return;const pl=S.plan;
 if(dir==='up'||dir==='down'){const ni=f.i+(dir==='up'?-1:1);if(ni<0||ni>=f.d.items.length){say(PL[k.pid].name+' is already '+(dir==='up'?'first':'last')+' on Day '+(f.d.n+1)+'.');return}f.d.items.splice(f.i,1);f.d.items.splice(ni,0,f.it)}
 else{const nd=f.d.n+(dir==='prev'?-1:1);if(nd<0||nd>=pl.days.length){say('No day '+(dir==='prev'?'before':'after')+' Day '+(f.d.n+1)+'.');return}f.d.items.splice(f.i,1);const t=pl.days[nd];t.items.splice(Math.min(f.i,t.items.length),0,f.it);U.day=nd}
 recalc(pl,S);render();focusRow(k.pid);say(PL[k.pid].name+' now '+posText(k.pid))}
function kbDrop(){const k=U.kb;if(!k)return;const f=find(k.pid);U.kb=null;if(!f){render();return}f.it.placed=true;recalc(S.plan,S);U.moved=[k.pid];U.justBuilt=false;const txt=posText(k.pid);commit('Moved '+PL[k.pid].name+' to Day '+(f.d.n+1)+', stop '+(f.d.items.indexOf(f.it)+1)+' · kept there');focusRow(k.pid);say('Dropped '+PL[k.pid].name+', '+txt+', kept there. Undo is in the message.')}
function kbCancel(quiet){const k=U.kb;if(!k)return;S.plan=J(k.snap);U.kb=null;recalc(S.plan,S);render();if(!quiet){focusRow(k.pid);say('Cancelled. '+PL[k.pid].name+' is back where it was.')}}
document.addEventListener('keydown',e=>{
 if(U.kb){const k=e.key;
  if(k==='Escape'){e.preventDefault();kbCancel();return}
  if(k==='Enter'){e.preventDefault();kbDrop();return}
  const m={ArrowUp:'up',ArrowDown:'down',ArrowLeft:'prev',PageUp:'prev',ArrowRight:'next',PageDown:'next'}[k];
  if(m){e.preventDefault();kbMoveBy(m);return}
  if(k===' '){e.preventDefault();kbDrop();return}
  if(k==='Tab'){kbCancel(true);return}return}
 if(e.key==='Escape'){if(U.sheets.length)closeSheet();else if(U.menu){U.menu=false;render()}}
 if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'&&!/INPUT|TEXTAREA/.test(document.activeElement.tagName)&&S.plan&&S.stage===7){e.preventDefault();e.shiftKey?redo():undo()}
 const t=e.target,row=t.closest&&t.closest('.it');
 if(!row||!t.matches('button[data-row]')||e.metaKey||e.ctrlKey||e.altKey||!S.plan||S.stage!==7||U.sheets.length)return;
 const pid=row.dataset.pid,key=e.key;
 if(key==='ArrowUp'||key==='ArrowDown'){e.preventDefault();const all=[...document.querySelectorAll('.it button[data-row]')];const i=all.indexOf(t);const n=all[i+(key==='ArrowUp'?-1:1)];if(n)n.focus();return}
 if(key===' '){e.preventDefault();kbLift(pid);return}
 if(key==='Delete'){e.preventDefault();const all=[...document.querySelectorAll('.it button[data-row]')],i=all.indexOf(t),nx=all[i+1]||all[i-1];const nid=nx&&nx.closest('.it').dataset.pid;A.remove(pid);if(nid)focusRow(nid);else{const ad=document.querySelector('.addrow');if(ad)ad.focus()}return}
 if(U.mpend&&/^[1-9]$/.test(key)){e.preventDefault();U.mpend=false;const d=+key-1;if(d<S.plan.days.length&&d!==find(pid).d.n){A.moveTo(pid+':'+d);focusRow(pid)}return}
 U.mpend=false;
 if(!U.keys||key.length!==1||e.shiftKey&&key!=='?')return;
 const lk=key.toLowerCase();
 if(lk==='m'){e.preventDefault();U.mpend=true;say('Move to which day? Press 1 to '+Math.min(9,S.plan.days.length));clearTimeout(U.mt);U.mt=setTimeout(()=>{U.mpend=false},3000)}
 else if(lk==='s'){e.preventDefault();openSheet('swap:'+pid)}
 else if(lk==='a'){e.preventDefault();openSheet('add:'+find(pid).d.n)}
 else if(key==='?'){e.preventDefault();openSheet('keys')}});
/* ---------- drag and drop: mouse (desktop) and long-press (phones) ---------- */
let dragPid=null;
function dropOn(pid,t){if(t.classList.contains('dc')){const d=+t.dataset.dn;op('Moved '+PL[pid].name,()=>moveItem(pid,d),[pid],'Moved to Day '+(d+1)+' · kept there');U.day=d}
 else{const tp=t.dataset.pid;if(tp===pid)return;const f=find(tp);op('Moved '+PL[pid].name,()=>moveItem(pid,f.d.n,f.i),[pid],'Moved · kept there')}render()}
document.addEventListener('dragstart',e=>{const it=e.target.closest&&e.target.closest('.it');if(!it)return;dragPid=it.dataset.pid;it.classList.add('dragging');e.dataTransfer.setData('text/plain',dragPid);e.dataTransfer.effectAllowed='move'});
document.addEventListener('dragover',e=>{const t=e.target.closest&&e.target.closest('.it,.dc');if(dragPid&&t){e.preventDefault();document.querySelectorAll('.over,.drop').forEach(x=>x.classList.remove('over','drop'));t.classList.add(t.classList.contains('dc')?'drop':'over')}});
document.addEventListener('drop',e=>{const t=e.target.closest&&e.target.closest('.it,.dc');if(!dragPid||!t)return;e.preventDefault();const pid=dragPid;dragPid=null;dropOn(pid,t)});
document.addEventListener('dragend',()=>{dragPid=null;document.querySelectorAll('.dragging,.over,.drop').forEach(x=>x.classList.remove('dragging','over','drop'))});
/* Long-press: touch and hold a stop for 300 ms (moving more than 10 px first is a scroll, not a lift). While lifted the day
   chips and the other stops are drop targets, and holding near the top or bottom edge of the list scrolls it. */
const TD={timer:0,pid:null,lifted:false,x:0,y:0,x0:0,y0:0,ghost:null,raf:0,over:null};
function tdClear(){clearTimeout(TD.timer);cancelAnimationFrame(TD.raf);TD.raf=0;if(TD.ghost){TD.ghost.remove();TD.ghost=null}document.body.classList.remove('lifting');document.querySelectorAll('.dragging,.over,.drop').forEach(x=>x.classList.remove('dragging','over','drop'));TD.lifted=false;TD.pid=null;TD.over=null}
function tdHover(){const g=TD.ghost;if(g)g.style.display='none';const el=document.elementFromPoint(TD.x,TD.y);if(g)g.style.display='';const t=el&&el.closest&&el.closest('.it,.dc');
 document.querySelectorAll('.over,.drop').forEach(x=>x.classList.remove('over','drop'));TD.over=null;if(t&&!(t.classList.contains('it')&&t.dataset.pid===TD.pid)){t.classList.add(t.classList.contains('dc')?'drop':'over');TD.over=t}}
function tdScroll(){if(!TD.lifted)return;const b=$('#body');if(b){const r=b.getBoundingClientRect(),zone=64;let v=0;if(TD.y<r.top+zone)v=-Math.ceil((r.top+zone-TD.y)/6);else if(TD.y>r.bottom-zone)v=Math.ceil((TD.y-(r.bottom-zone))/6);if(v){b.scrollTop+=v;tdHover()}}TD.raf=requestAnimationFrame(tdScroll)}
function tdLift(it,t){TD.lifted=true;TD.x=t.clientX;TD.y=t.clientY;it.classList.add('dragging');document.body.classList.add('lifting');
 const r=it.getBoundingClientRect(),g=it.cloneNode(true);g.className='it ghost';g.removeAttribute('draggable');g.style.cssText='position:fixed;left:'+r.left+'px;top:'+r.top+'px;width:'+r.width+'px;margin:0;pointer-events:none;z-index:80';document.body.appendChild(g);TD.ghost=g;TD.dx=t.clientX-r.left;TD.dy=t.clientY-r.top;
 try{navigator.vibrate&&navigator.vibrate(15)}catch(e){}say('Lifted '+PL[TD.pid].name+'. Drag onto a day above, or onto another stop, then let go.');TD.raf=requestAnimationFrame(tdScroll)}
document.addEventListener('touchstart',e=>{tdClear();if(e.touches.length!==1||!S||!S.plan||S.stage!==7||U.sheets.length)return;const it=e.target.closest&&e.target.closest('.it');if(!it)return;const t=e.touches[0];TD.pid=it.dataset.pid;TD.x0=t.clientX;TD.y0=t.clientY;TD.timer=setTimeout(()=>tdLift(it,t),300)},{passive:true});
document.addEventListener('touchmove',e=>{if(!TD.pid)return;const t=e.touches[0];
 if(!TD.lifted){if(Math.hypot(t.clientX-TD.x0,t.clientY-TD.y0)>10)tdClear();return}
 e.preventDefault();TD.x=t.clientX;TD.y=t.clientY;if(TD.ghost)TD.ghost.style.transform='translate('+(TD.x-TD.dx-parseFloat(TD.ghost.style.left))+'px,'+(TD.y-TD.dy-parseFloat(TD.ghost.style.top))+'px)';tdHover()},{passive:false});
document.addEventListener('touchend',e=>{if(!TD.pid)return;if(!TD.lifted){tdClear();return}e.preventDefault();const pid=TD.pid,t=TD.over;tdClear();if(t)dropOn(pid,t);else say('Dropped. Nothing moved.')});
document.addEventListener('touchcancel',()=>tdClear());
document.addEventListener('keyup',e=>{if(e.key===' '&&e.target.matches&&e.target.matches('button[data-row]'))e.preventDefault()});
document.addEventListener('contextmenu',e=>{if(TD.lifted||TD.pid)e.preventDefault()});
window.addEventListener('beforeprint',()=>{U.printTheme=document.documentElement.dataset.theme;document.documentElement.dataset.theme='light';fillPrint()});
window.addEventListener('afterprint',()=>{if(U.printTheme)document.documentElement.dataset.theme=U.printTheme});

/* ---------- init, seeding, URL contract ---------- */
function withState(s,fn){const keep=S;S=s;try{fn()}finally{S=keep}}
function seed(){if(trips.read().length)return;const ids=IDS();
 let a=newState('weekend',{party:[{id:1,name:'Nitin',type:'adult',needs:[],decider:true},{id:2,name:'',type:'adult',needs:[]},{id:3,name:'',type:'child',age:6,needs:[]}],when:{type:'dates',from:'2027-06-18',to:'2027-06-20'},picks:['huntsville','algonquin','arrowhead','lookout-trail','spruce-bog'],stay:{huntsville:true},nights:2,identity:ids[0],title:'Algonquin weekend from Toronto'});
 withState(a,()=>{S.plan=buildPlan(S,null);S.unfit=S.plan.unfit;S.cfg0=cfgSig(S);S.checklist=defaultChecklist();histReset('Built');save(true)});
 let b=newState('weekair',{when:{type:'dates',from:'2027-07-13',to:'2027-07-22'},picks:['ortisei','cortina','seceda','siusi','braies','funes','tre-cime','carezza','gherdeina','cinque'],stay:{ortisei:true,cortina:true},nights:9,identity:ids[1],title:'Dolomites · 10 days'});
 withState(b,()=>{S.plan=buildPlan(S,null);S.unfit=S.plan.unfit;S.cfg0=cfgSig(S);S.checklist=defaultChecklist();histReset('Built');save(true)});
 localStorage.removeItem('proto.draft')}
function init(){U.keys=store.get('proto.builder.keys',1)!==0;seed();const q=new URLSearchParams(location.search);S=newState('weekend');S.stage=0;U.fast=q.has('fast');
 const m=q.get('m'),n=q.get('n'),p=q.get('p'),cc=q.get('cc'),add=q.get('add'),save_=q.get('save'),edit=q.get('edit'),rev=q.get('review'),cp=q.get('copy');
 if(edit||rev){const id=edit||rev;if(openDraft(id)){histReset('Opened');S.stage=rev?8:7;if(q.get('day'))U.day=Math.max(0,+q.get('day')-1)}else{toast('That trip was not found')}}
 else if(cp){if(cp==='dolomites'){copyCreateNow()}else if(openDraft(cp)){A.duplicate();S.title=S.title.replace(' (copy)','')+' (copy)';S.stage=7;histReset('Copied')}}
 else if(m){if(p&&!PARKS[p])ensurePark(p);U.ctx={};if(p&&PARKS[p]){U.ctx.area=p;U.ctx.cc=PARKS[p].cc}if(cc)U.ctx.cc=cc;
  if(m==='near'){const nn=Math.max(0,+n||0);const kind=nn===0?'day':nn===1?'weekend':'long';chooseKind(kind);if(kind!=='day'){S.nights=nn;S.nightsTouched=true}}
  else{chooseKind('weekair');if(n&&+n>0){S.nights=+n;S.nightsTouched=true}if(cc&&COUNTRIES[cc]){S.cc=cc;if(!S.area){S.macro=COUNTRIES[cc].macros[0].id;S.regions=[COUNTRIES[cc].macros.flatMap(x=>x.regions).find(r=>PLACES.some(pl=>pl.reg===r))]}}setAirports(S)}
  S.stage=1}
 else if(add){const park=p||(add.includes('--')?add.split('--')[0]:null);if(park)ensurePark(park);const pl=resolvePlace(add,park);if(pl){const cur=localStorage.getItem('proto.draft');const has=cur&&openDraft(cur);if(has&&S.plan){histReset('Opened');addToBestDay(pl.id);S.stage=7}else if(has){if(!S.picks.includes(pl.id))S.picks.push(pl.id);S.stage=3;save()}else{U.ctx={area:pl.park&&PARKS[pl.park]?pl.park:null,cc:pl.cc,regions:[pl.reg]};if(pl.cc==='CA'&&pl.reg!=='ontario')U.ctx.macro='west';chooseKind(pl.reg==='ontario'?'weekend':'weekair');S.picks=[pl.id];S.stage=0;U.fromAdd=pl.name;save()}}}
 else if(save_){const park=PARKS[save_];const pl=resolvePlace(save_);const cur=localStorage.getItem('proto.draft');
  if(cur&&openDraft(cur)){if(park){S.area=save_;S.stage=S.plan?7:3}else if(pl){if(S.plan){histReset('Opened');addToBestDay(pl.id);S.stage=7}else{if(!S.picks.includes(pl.id))S.picks.push(pl.id);S.stage=3}}save()}
  else if(park){U.ctx={area:save_,cc:park.cc};chooseKind(park.type==='trip'?'weekair':'weekend')}else if(pl){A.fromSaved(save_);}}
 else if(q.get('saved')){S.stage=0;U.savedFocus=true}
 else if(cp==null){const dr=q.get('draft');}
 if(q.get('theme')==='dark'||q.get('theme')==='light')ProtoTheme.set(q.get('theme'));
 if(q.has('desk'))U.desk=true;
 render();
 if(U.fromAdd)toast(U.fromAdd+' is picked. Choose a kind of trip to go on.');
 if(U.savedFocus){setTimeout(()=>{const e=[...document.querySelectorAll('.cap')].find(x=>/saved places/.test(x.textContent));if(e)e.scrollIntoView()},50)}}
window.addEventListener('load',init);

if(DMQ.addEventListener)DMQ.addEventListener('change',()=>{if(S)render()});
document.body.classList.toggle('dsk',DMQ.matches);
